const VAGAR = ['dag', 'bo', 'bat', 'barn', 'aktiv', 'bor', 'visa']
const BAS = 'https://upload.wikimedia.org/wikipedia/commons/'
const TUMME = 'https://thumb.wikimedia.org/wikipedia/commons/thumb/'
function koda(fil: string): string {
  return encodeURIComponent(fil.replace(/ /g, '_')).replace(/[!'()*]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase())
}
function bild(i: number | null | undefined, bredd: 960 | 1920, ovrig = false): Bild | undefined {
  if (i == null) return undefined
  const r = F[i]
  if (!r) return undefined
  const [fil, h, l, a, s] = r
  let url: string
  if (!h) url = fil
  else {
    const k = koda(fil)
    const sti = h.charAt(0) + '/' + h + '/' + k
    const original = s === 2 || (bredd === 1920 && s === 1)
    url = original ? BAS + sti : TUMME + sti + '/' + bredd + 'px-' + k
  }
  const b: Bild = { url, fotograf: FOT[a] ?? '', licens: LIC[l] ?? '', fil }
  if (ovrig) b.ovrig = true
  return b
}
/** Öns toppbild, 1920 px bred när filen räcker till. */
export function toppbild(slug: string): Bild | undefined {
  return bild(D[slug]?.[0], 1920)
}
/** Bild till vägkortet. Saknas exakt bild används ett foto från ön (ovrig). */
export function vagbild(slug: string, vag: string): Bild | undefined {
  const i = VAGAR.indexOf(vag)
  if (i < 0) return undefined
  return bild(D[slug]?.[1][i], 960) ?? bild(D[slug]?.[3][i], 960, true)
}
/** Bild på ett ställe, nyckel = namnet exakt som i island-data. Saknas exakt bild används ett foto från ön (ovrig). */
export function platsbild(slug: string, namn: string): Bild | undefined {
  return bild(D[slug]?.[2][namn], 960) ?? bild(D[slug]?.[4][namn], 960, true)
}
